// Regenerates `forge-web-meshes.json`: real `forge_mesh::tessellate_render` output (what the
// app's default engine hands the viewport: vertices split per face, each carrying its face's
// exact surface normal) for the measure tests. Run after building @aicad/forge-web:
//
//   node packages/app/test/fixtures/gen-forge-web-meshes.mjs
//
// Programs:
// - `nema`: the NEMA 17 plate (corpus/makerbench/t1-nema17-plate.cad.ts) as IR v0.
// - `wedge15`: an offset rectangle (r 2…3, z 0…1) revolved 15°: every arc edge is ONE segment
//   (15° < the 0.35 rad angular limit, sagitta < 0.05 mm) and both cylinder walls are single
//   quads, so the positions alone look exactly like a planar hexahedron.
// - `wedge45`: the same revolved 45°: arcs of 3 segments (4 points).
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const forgeWeb = join(here, "../../../forge-web");
const { init, evaluate, engineVersion } = await import(join(forgeWeb, "dist/index.js"));
await init(readFileSync(join(forgeWeb, "pkg/forge_wasm_bg.wasm")));

const line = (id, start, end) => ({ kind: "line", id, start, end });
const circle = (id, center, radius) => ({ kind: "circle", id, center, radius });

const nema = {
  schema: "aicad.ir/0",
  meta: { name: "nema17_plate" },
  parts: [
    {
      id: "p1",
      name: "plate",
      features: [
        {
          type: "sketch",
          id: "s1",
          name: "outline",
          plane: "XY",
          curves: [
            line("bottom", [-25, -25], [25, -25]),
            line("right", [25, -25], [25, 25]),
            line("top", [25, 25], [-25, 25]),
            line("left", [-25, 25], [-25, -25]),
            circle("pilot", [0, 0], 11),
            circle("m3_a", [15.5, 15.5], 1.7),
            circle("m3_b", [-15.5, 15.5], 1.7),
            circle("m3_c", [-15.5, -15.5], 1.7),
            circle("m3_d", [15.5, -15.5], 1.7),
          ],
        },
        { type: "extrude", id: "e1", name: "plate", sketch: "outline", distance: 5 },
      ],
    },
  ],
};

const wedge = (angle) => ({
  schema: "aicad.ir/0",
  meta: { name: `wedge${angle}` },
  parts: [
    {
      id: "p1",
      name: "w",
      features: [
        {
          type: "sketch",
          id: "s1",
          name: "profile",
          plane: "XZ",
          curves: [line("inner", [2, 0], [2, 1]), line("top", [2, 1], [3, 1]), line("outer", [3, 1], [3, 0]), line("bottom", [3, 0], [2, 0])],
        },
        { type: "revolve", id: "r1", name: "wedge", sketch: "profile", axis: { origin: [0, 0], direction: [0, 1] }, angle },
      ],
    },
  ],
});

const out = { engine: engineVersion(), note: "generated by gen-forge-web-meshes.mjs; do not edit", bodies: {} };
for (const [key, ir] of Object.entries({ nema, wedge15: wedge(15), wedge45: wedge(45) })) {
  const r = evaluate(JSON.stringify(ir));
  if (r.report.status !== "ok" || r.bodies.length !== 1 || r.meshErrors.length > 0) throw new Error(`${key}: ${JSON.stringify(r.report.errors ?? r.meshErrors)}`);
  const b = r.bodies[0];
  out.bodies[key] = {
    name: b.name,
    positions: Array.from(b.positions),
    normals: Array.from(b.normals),
    indices: Array.from(b.indices),
    faceRanges: b.faceRanges,
    edges: b.edges.map((e) => ({ edge: e.edge, points: Array.from(e.points) })),
  };
}
writeFileSync(join(here, "forge-web-meshes.json"), `${JSON.stringify(out)}\n`);
console.log(Object.entries(out.bodies).map(([k, b]) => `${k}: ${b.name}, ${b.positions.length / 3} vertices, ${b.faceRanges.length} faces, ${b.edges.length} edges`).join("\n"));
